"use client"
import { useParams } from "next/navigation";
import ListGroup from "react-bootstrap/ListGroup";
import ListGroupItem from "react-bootstrap/ListGroupItem"
import FormControl from "react-bootstrap/FormControl";
import Button from "react-bootstrap/Button";
import { BsGripVertical } from "react-icons/bs";
import ModulesControls from "./ModulesControls";
import ModuleControlButtons from "./ModuleControlButtons";
import LessonControlButtons from "./LessonControlButtons";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "@/app/(kambaz)/store";
import { addModule, deleteModule, updateModule, editModule as editModuleAction } from "@/app/(kambaz)/courses/[cid]/modules/reducer";

type Lesson = {
  _id: string;
  name: string;
  description?: string;
  module: string;
};

type Module = {
  _id: string;
  name: string;
  description: string;
  course: string;
  lessons?: Lesson[];
  editing?: boolean;
};

export default function Modules() {
  const dispatch = useDispatch();
  const { cid } = useParams<{ cid: string }>();
  const { modules } = useSelector((state: RootState) => state.modulesReducer);

  const courseModules = (modules as Module[]).filter((module) => module.course === cid);


  return (
    <div>
      <ModulesControls
        moduleName={module.name}
        setModuleName={(name: string) => setModule({ ...module, name })}
        addModule={addNewModule}
      />
      <br />

      <FormControl
        className="mb-2"
        value={module.name}
        onChange={(event) => setModule({ ...module, name: event.target.value })}
      />
      <FormControl
        as="textarea"
        rows={3}
        className="mb-2"
        value={module.description}
        onChange={(event) =>
          setModule({ ...module, description: event.target.value })
        }
      />
      <div className="mb-4">
        <Button variant="warning" onClick={saveModule}>
          Update Module
        </Button>
      </div>

      <ListGroup className="rounded-0" id="wd-modules">
        {courseModules.map((module) => (
          <ListGroupItem key={module._id} className="wd-module p-0 mb-5 fs-5 border-gray">
            <div className="wd-title p-3 ps-2 bg-secondary">
              <BsGripVertical className="me-2 fs-3" />
              {module.editing ? (
                <input
                  autoFocus
                  type="text"
                  value={module.name}
                  onChange={(e) => updateModuleState({ ...module, name: e.target.value })}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      updateModuleState({ ...module, editing: false });
                    }
                  }}
                  className="form-control d-inline-block w-50"
                />
              ) : (
                <>{module.name}</>
              )}
              <ModuleControlButtons moduleId={module._id} editModule={editModule} deleteModule={removeModule} />
              <button
                className="btn btn-sm btn-warning float-end me-2"
                onClick={() => setModule(module)}
                id="wd-edit-module-click"
              >
                Edit
              </button>
              <button
                className="btn btn-sm btn-danger float-end me-2"
                onClick={() => removeModule(module._id)}
                id="wd-delete-module-click"
              >
                Delete
              </button>
            </div>

            <ListGroup className="wd-lessons rounded-0">
              {module.lessons && module.lessons.map((lesson) => (
                <ListGroupItem key={lesson._id} className="wd-lesson p-3 ps-1">
                  <BsGripVertical className="me-2 fs-3" />
                  {lesson.name}
                  <LessonControlButtons />
                </ListGroupItem>
              ))}
            </ListGroup>
          </ListGroupItem>
        ))}
      </ListGroup>
    </div>
  );
}
